package com.novacommerce.order.application; import com.novacommerce.order.domain.cart.CartItem; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public class CheckoutHasher{public String hash(UUID owner,UUID cart,Collection<CartItem>items){try{String lines=items.stream().sorted(Comparator.comparing(CartItem::getVariantId)).map(i->i.getVariantId()+":"+i.getQuantity()).reduce((a,b)->a+"|"+b).orElse("");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((owner+"|"+cart+"|"+lines).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
